use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->Wfc3dSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let text=|v:&serde_json::Value|v.as_str().unwrap().to_string();let word=|v:&serde_json::Value|f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap());Wfc3dSnapshot{schema:text(&f["schema"]),seed:f["seed"].as_str().unwrap().parse().unwrap(),tiles:f["tiles"].as_array().unwrap().iter().map(|t|{let m=&t["media"];let media=match m["kind"].as_str().unwrap(){"mesh"=>TileMedia3d::Mesh{positions:m["positionsBits"].as_array().unwrap().iter().map(word).collect(),indices:m["indices"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as u32).collect(),color:m.get("color").map(|c|Color{r:c["r"].as_u64().unwrap() as u8,g:c["g"].as_u64().unwrap() as u8,b:c["b"].as_u64().unwrap() as u8,a:c["a"].as_u64().unwrap() as u8})},"meshChild"=>{let v=&m["target"];TileMedia3d::MeshChild{child:store::ArtifactChild::new(text(&m["childId"]),store::os_io::ArtifactRef{artifact_id:text(&v["artifactId"]),dialect:store::os_io::ArtifactDialect{artifact_kind:text(&v["dialect"]["artifactKind"]),standard:text(&v["dialect"]["standard"]),subset:text(&v["dialect"]["subset"])}})}},_=>panic!("fixture kind")};Tile{id:text(&t["id"]),label:t.get("label").map(text),weight:word(&t["weightBits"]),media}}).collect(),slots:f["slots"].as_array().unwrap().iter().map(|s|Slot3d{id:text(&s["id"]),x:word(&s["xBits"]),y:word(&s["yBits"]),z:word(&s["zBits"]),width:word(&s["widthBits"]),height:word(&s["heightBits"]),depth:word(&s["depthBits"]),pinned_tile_id:s.get("pinnedTileId").map(text)}).collect(),edges:f["edges"].as_array().unwrap().iter().map(|e|SlotEdge{id:text(&e["id"]),from_slot_id:text(&e["fromSlotId"]),to_slot_id:text(&e["toSlotId"]),relation:text(&e["relation"])}).collect(),rules:f["rules"].as_array().unwrap().iter().map(|r|GraphRule{id:text(&r["id"]),tile_a_id:text(&r["tileAId"]),tile_b_id:text(&r["tileBId"]),relation:r.get("relation").map(text),allowed:r["allowed"].as_bool().unwrap()}).collect()}}
fn project(s:&Wfc3dSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<Wfc3dSnapshot,String>{Wfc3dSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_wfc3d_all_owned_graph_and_word_states(){let s=fixture();let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&actual),d);assert_eq!(actual.slots[0].x.to_bits(),0x8000000000000000);assert_eq!(actual.slots[0].y.to_bits(),0x7ff0000000000001);assert_eq!(actual.slots[0].pinned_tile_id,Some("".into()));assert_eq!(actual.rules[0].relation,None);assert_eq!(actual.rules[1].relation,Some("".into()));assert_eq!(store::ArtifactPack::encode_pack(&actual),store::ArtifactPack::encode_pack(&s));assert_eq!(store::ArtifactDsl::print_dsl(&actual),store::ArtifactDsl::print_dsl(&s));assert_eq!(restore(&project(&Wfc3dSnapshot::default())).unwrap(),Wfc3dSnapshot::default());}
#[test]fn sqlite_snapshot_wfc3d_independent_sql_join_and_edge_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=d.query('SELECT s.authored_id AS slot,t.authored_id AS tile FROM wfc3d_slot s JOIN wfc3d_tile t ON pinned_tile_id=t.id').get();if(r.slot!=='box'||r.tile!=='')throw Error('pin relationship');if(d.query('SELECT relation FROM wfc3d_rule ORDER BY ordinal').all().map(r=>r.relation).join('|')!=='||above 世界')throw Error('optional relation');d.query('UPDATE wfc3d_slot_edge SET relation=?').run('independent');await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let actual=restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(actual.edges[0].relation,"independent");}
#[test]fn sqlite_snapshot_wfc3d_graph_corruption_and_controls(){let d=project(&fixture());for n in 0..6{let mut m=d.clone();match n{0=>m.table_mut("wfc3d_slot_edge").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>m.table_mut("wfc3d_rule").unwrap().rows[0].values[5]=SqliteValue::Integer(999),2=>m.table_mut("wfc3d_slot").unwrap().rows[0].values[10]=SqliteValue::Integer(999),3=>m.table_mut("wfc3d_color").unwrap().rows[0].values[1]=SqliteValue::Integer(256),4=>m.table_mut("wfc3d_position").unwrap().rows[0].values[2]=SqliteValue::Integer(99),_=>m.table_mut("wfc3d_slot").unwrap().rows[0].values[11]=SqliteValue::Integer(1)};assert!(restore(&m).is_err())}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(Wfc3dSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4,..SqliteDatabaseLimits::default()})).is_err());}

#[test]fn sqlite_snapshot_wfc3d_actual_owner_native_admission(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.wfc3d".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=(provider.import)("wfc3d",&dialect,project(&s),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}let wrong=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.wfc3d".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
